	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeSubscription__c/GladeSubscription__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>GladeSubscription__c</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>GladeSubscription__c Rows</pluralLabel><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeOrderProduct__c/recordTypes/Merchandise.recordType-meta.xml"), "<RecordType xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Merchandise</fullName><active>true</active><label>Merchandise</label></RecordType>\n")
