	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeOrderProduct__c/fields/RecordTypeName__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>RecordTypeName__c</fullName><defaultValue>$RecordType.Name</defaultValue><label>Record Type Name</label><length>255</length><type>Text</type></CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeSubscription__c/fields/EndDate__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>EndDate__c</fullName><label>End Date</label><type>Date</type></CustomField>\n")
