	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeSubscription__c/validationRules/EndDateLastDayOfMonth.validationRule-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ValidationRule xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <fullName>EndDateLastDayOfMonth</fullName>\n    <active>true</active>\n    <description>The End Date must be the last day of the month.</description>\n    <errorConditionFormula>AND (IsBlank(EndDate__c) = False,\nDAY(EndDate__c) &lt;&gt;\nIF(Month(EndDate__c)=12, 31,\nDAY(DATE(YEAR(EndDate__c),MONTH(EndDate__c)+1,1) - 1))\n)</errorConditionFormula>\n    <errorMessage>The End Date must be the last day of the month</errorMessage>\n</ValidationRule>\n\n")
